insert into org.jornada (codigo, circulo, nome, dominio, classe, onda, objetivo, frequencia, automacao_nivel, automacao_motivo, raias) select codigo, circulo, nome, dominio, classe, onda, objetivo, frequencia, automacao_nivel, automacao_motivo, raias from jsonb_to_recordset($j$[{"codigo": "ID-01", "circulo": 1, "nome": "Definir e revisar propósito, visão, missão, princípios e valores", "dominio": "Fundamento", "classe": "essencial", "onda": 1, "objetivo": "Manter uma declaração de identidade única, aprovada pelos sócios, que diga o que vale para todo o Ecossistema e o que é próprio de cada empresa.", "frequencia": "Rara: por evento (empresa nova) ou quando a avaliação da ID-05 decide rever a declaração", "automacao_nivel": "média", "automacao_motivo": "Decisão humana e pouco frequente. O fluxo serve de roteiro, não de automação.", "raias": ["Estratégia", "Sócios", "Governança", "Executivo da empresa", "Identidade · pessoa", "Identidade · agente", "Identidade · automação"]}, {"codigo": "ID-02", "circulo": 1, "nome": "Transformar a identidade em regras práticas para pessoas e agentes", "dominio": "Fundamento", "classe": "essencial", "onda": 1, "objetivo": "Converter a declaração em padrões que qualquer pessoa ou agente aplica sem consultar o fundador, entregar a cada círculo que executa o conjunto de padrões de que ele precisa e responder às consultas sobre casos que o padrão não cobre.", "frequencia": "Por evento: nova versão da declaração, revisão decidida na ID-05, agente ou canal novo, consulta sobre caso não coberto", "automacao_nivel": "média (alta nas consultas, média na redação)", "automacao_motivo": "Responder consulta já coberta pelo padrão, publicar e carregar nos agentes rodam sem pessoa. Interpretar caso novo e redigir padrão são de copiloto.", "raias": ["Solicitante", "Integração", "Sócios", "Governança", "Gestão", "Relações", "Identidade · pessoa", "Identidade · agente", "Identidade · automação"]}, {"codigo": "ID-03", "circulo": 1, "nome": "Criar ou rever e registrar a marca de uma empresa, oferta ou projeto", "dominio": "Marca", "classe": "essencial", "onda": 2, "objetivo": "Decidir se o negócio novo usa uma marca existente ou ganha marca própria e, quando ganha, entregá-la criada, protegida e pronta para uso por pessoas e agentes. Vale também para rever uma marca existente, receber a marca de uma empresa adquirida e retirar uma marca de uso. Quem usa a marca produz os materiais com o pacote.", "frequencia": "Por evento: empresa, oferta ou projeto novo, empresa adquirida, vendida ou encerrada, ou revisão de marca decidida na ID-05", "automacao_nivel": "média", "automacao_motivo": "Pesquisa, alternativas e pacote são de agente; arquitetura, nome e registro são decisão humana.", "raias": ["Solicitante", "Estratégia", "Executivo da empresa", "Assessoria externa", "Governança", "Identidade · pessoa", "Identidade · agente", "Identidade · automação"]}, {"codigo": "ID-04", "circulo": 1, "nome": "Definir o posicionamento institucional e as mensagens para cada público", "dominio": "Posicionamento", "classe": "essencial", "onda": 2, "objetivo": "Definir uma promessa clara e as mensagens principais para cada público, no nível do Ecossistema e de cada empresa, para uso de pessoas e agentes. Quem comunica são Relações, para fora, e a Gestão, para dentro.", "frequencia": "A cada ciclo estratégico e por evento: nova declaração ou revisão decidida na ID-05", "automacao_nivel": "baixa", "automacao_motivo": "Síntese e redação são de agente; escolha e aprovação são humanas.", "raias": ["Estratégia", "Relações", "Gestão", "Integração", "Identidade · pessoa", "Identidade · agente", "Identidade · automação"]}, {"codigo": "ID-05", "circulo": 1, "nome": "Avaliar se os padrões de identidade funcionam e decidir o que rever", "dominio": "Avaliação", "classe": "essencial", "onda": 2, "objetivo": "Saber, com os dados de quem executa e de quem audita, onde o que declaramos, o que vivemos e como somos vistos não batem; separar falha do padrão de falha de execução; e abrir a revisão do padrão certo.", "frequencia": "A cada ciclo de avaliação (cadência: semestral) e por evento: depois de crise, de empresa que entra ou sai do portfólio, ou de troca de liderança", "automacao_nivel": "alta", "automacao_motivo": "Reunir, consolidar e calcular são de agente e automação; interpretar e decidir o que rever são de pessoas.", "raias": ["Identidade · pessoa", "Identidade · agente", "Identidade · automação"]}, {"codigo": "ES-01", "circulo": 2, "nome": "Formular e revisar a estratégia do Ecossistema e de cada empresa", "dominio": "Direção e recursos", "classe": "essencial", "onda": 1, "objetivo": "Ter uma estratégia escrita e aprovada, do Ecossistema e de cada empresa, que diga onde atuar, o que não fazer e para quem, com as hipóteses de cada escolha, e que sirva de critério para alocar recursos e fixar alvos. Inclui as escolhas de cada círculo e o método de estratégia, que os sócios aprovam junto com a estratégia. A Estratégia formula; o executivo e o líder do círculo propõem e participam.", "frequencia": "A cada ciclo estratégico (cadência: anual, com revisão no meio do ciclo) e por evento: mudança relevante de cenário, empresa nova no portfólio ou revisão decidida na ES-06", "automacao_nivel": "média", "automacao_motivo": "Decisão humana, de risco alto e pouco frequente. O agente reúne evidências, monta opções e confere a coerência; a escolha é de pessoas da Estratégia e a aprovação é dos sócios.", "raias": ["Inteligência", "Sócios", "Governança", "Executivo da empresa", "Líder do círculo", "Identidade", "Estratégia · pessoa", "Estratégia · agente", "Estratégia · automação"]}, {"codigo": "ES-02", "circulo": 2, "nome": "Rever o portfólio e realocar recursos entre empresas, ofertas e apostas", "dominio": "Direção e recursos", "classe": "essencial", "onda": 2, "objetivo": "Decidir, a cada período, para onde vão dinheiro, pessoas e atenção: o que recebe mais, o que mantém, o que perde recursos e o que deve ter a saída estudada, e o destino do resultado de cada empresa. A proposta sobe sempre aos sócios, mesmo quando é manter a alocação.", "frequencia": "A cada fechamento de período (cadência: semestral) e por evento: estratégia nova ou revisão decidida na ES-06", "automacao_nivel": "média", "automacao_motivo": "O agente compara o uso de recursos com o portfólio-alvo e simula realocações; a proposta é de pessoas da Estratégia e a decisão é dos sócios.", "raias": ["Gestão", "Assessoria externa", "Identidade", "Governança", "Sócios", "Executivo da empresa", "Estratégia · pessoa", "Estratégia · agente", "Estratégia · automação"]}, {"codigo": "ES-03", "circulo": 2, "nome": "Desdobrar a estratégia em alvos e iniciativas de cada empresa e de cada círculo", "dominio": "Direção e recursos", "classe": "essencial", "onda": 1, "objetivo": "Transformar a estratégia em poucos alvos mensuráveis do Ecossistema, de cada empresa e de cada círculo, com iniciativas, dono e indicador, combinados de cima para baixo e de baixo para cima; pedir à Inteligência a ficha do indicador de cada alvo antes da aprovação; e conferir com a Gestão e a Integração se os alvos cabem nos recursos.", "frequencia": "A cada ciclo de alvos (cadência: anual, com o ciclo) e por evento: estratégia nova, portfólio de empresas atualizado, alocação que muda alvos ou orçamento, ou correção decidida na ES-06", "automacao_nivel": "média", "automacao_motivo": "O agente desdobra, confere a soma e aponta conflitos; a negociação dos alvos é entre pessoas e a aprovação é dos sócios.", "raias": ["Sócios", "Governança", "Executivo da empresa", "Líder do círculo", "Identidade", "Gestão", "Integração", "Estratégia · pessoa", "Estratégia · agente", "Estratégia · automação"]}, {"codigo": "ES-04", "circulo": 2, "nome": "Decidir em cada portão se uma aposta avança, espera, volta para ajuste ou é encerrada", "dominio": "Apostas e empresas", "classe": "essencial", "onda": 2, "objetivo": "Fazer cada ideia, oferta ou negócio novo passar por decisões explícitas antes de receber recursos: entrar na carteira e, depois de produtizada pela Inteligência, ser lançada. Em qualquer portão ou revisão, a aposta pode avançar, seguir como está, esperar, voltar para ajuste ou ser encerrada. A Estratégia decide, ouvido o executivo, dentro da alçada; decidem os sócios quando os recursos passam da alçada, quando se encerra oferta com contratos vigentes e quando a decisão contraria o portfólio-alvo. Encerrar aposta em desenvolvimento ou oferta em uso só termina com o plano de saída conferido, a data de saída decidida por pessoa e a saída conferida.", "frequencia": "Por evento: ideia nova, aposta definida no portfólio-alvo, oferta pronta para lançar, aposta devolvida pela Inteligência, revisão pedida (a de oferta em uso chega pela Inteligência ou pela ES-06), estudo de saída pedido na ES-02, caso de empresa nascido de aposta e arquivado na ES-05, ou data de revisão ou de retomada da aposta", "automacao_nivel": "alta na entrada e na preparação, baixa na decisão", "automacao_motivo": "Registrar, completar o dossiê, estimar e encaminhar rodam com agente e automação; a decisão do portão e a data de saída são de pessoas.", "raias": ["Solicitante", "Inteligência", "Identidade", "Governança", "Sócios", "Executivo da empresa", "Estratégia · pessoa", "Estratégia · agente", "Estratégia · automação"]}, {"codigo": "ES-05", "circulo": 2, "nome": "Decidir e estruturar a criação, a aquisição, a venda ou o encerramento de uma empresa", "dominio": "Apostas e empresas", "classe": "essencial", "onda": 3, "objetivo": "Decidir com um caso escrito se o Ecossistema cria, adquire, vende ou encerra uma empresa; obter dos sócios a autorização para negociar e, depois, a decisão, inclusive a de arquivar o caso que eles mandaram estudar ou cuja negociação autorizaram; firmar o contrato, quando há; emitir o mandato para os círculos que executam; e conferir o cumprimento. A Integração executa o mandato; a Estratégia confere.", "frequencia": "Rara: por evento", "automacao_nivel": "média", "automacao_motivo": "Decisão dos sócios, rara e de risco alto. O agente monta o caso, os cenários e o mandato e confere a execução.", "raias": ["Solicitante", "Sócios", "Assessoria externa", "Governança", "Gestão", "Identidade", "Integração", "Estratégia · pessoa", "Estratégia · agente", "Estratégia · automação"]}, {"codigo": "ES-06", "circulo": 2, "nome": "Acompanhar a execução da estratégia e corrigir o rumo", "dominio": "Acompanhamento", "classe": "essencial", "onda": 1, "objetivo": "Saber a cada revisão se a estratégia está sendo executada e se as hipóteses continuam de pé, separar falha de execução de hipótese errada, decidir as correções de execução, ouvidos os executivos, abrir só a revisão de nível mais alto que os sócios decidem (a estratégia puxa o portfólio, que puxa os alvos) e prestar contas. Usa as comparações que a Inteligência e a Gestão já fazem, num painel único.", "frequencia": "A cada revisão da estratégia (cadência: trimestral) e por evento, quando o ritual da Gestão aponta desvio grave", "automacao_nivel": "alta", "automacao_motivo": "O agente reúne os resultados, aponta os desvios e propõe causas; a Inteligência responde com os dados; a decisão de corrigir e a prestação de contas são de pessoas.", "raias": ["Gestão", "Executivo da empresa", "Estratégia · pessoa", "Estratégia · agente", "Estratégia · automação"]}, {"codigo": "IN-01", "circulo": 3, "nome": "Ler o mercado, os clientes e os concorrentes e avisar das mudanças relevantes", "dominio": "Mercado e decisão", "classe": "essencial", "onda": 1, "objetivo": "Manter uma leitura atual de mercado, clientes e concorrentes, guiada pelas perguntas de quem decide, e avisar a tempo quando um sinal muda uma hipótese da estratégia ou abre uma oportunidade. Os sinais internos (clientes, vendas e entrega) chegam como dado do catálogo de dados, e a leitura só é publicada depois de classificada.", "frequencia": "A cada ciclo de leitura (cadência: mensal) e por evento: perguntas ou hipóteses novas da Estratégia, ou sinal detectado pelo critério de aviso", "automacao_nivel": "alta", "automacao_motivo": "Coletar, vigiar, registrar, agrupar e redigir são de agente e automação; combinar as perguntas com quem decide, julgar a relevância, emitir o aviso e aprovar a leitura são de pessoas.", "raias": ["Estratégia", "Relações", "Negócios", "Inteligência · pessoa", "Inteligência · agente", "Inteligência · automação"]}, {"codigo": "IN-02", "circulo": 3, "nome": "Responder a perguntas de decisão com evidência", "dominio": "Mercado e decisão", "classe": "essencial", "onda": 1, "objetivo": "Dar a quem vai decidir uma resposta com fonte e grau de confiança, dentro do prazo combinado, e guardar a pergunta, a resposta e o uso para que a próxima seja mais rápida. É por aqui que a Estratégia pede a evidência de um portão ou de um caso e a contestação das causas de um desvio: essas respostas são revistas por pessoa e ficam restritas a quem pode vê-las.", "frequencia": "Por evento: cada pergunta de quem vai decidir, de qualquer círculo, empresa ou portão. O volume não foi medido", "automacao_nivel": "alta", "automacao_motivo": "Registrar, buscar, avaliar, montar e entregar a resposta rodam com agente e automação. A pessoa entra para classificar a pergunta sigilosa, na recusa, quando falta evidência e quando a resposta apoia decisão de portão, de caso de empresa, de alvos ou de risco alto. As demais respostas entram na amostra da Governança.", "raias": ["Solicitante", "Governança", "Inteligência · pessoa", "Inteligência · agente", "Inteligência · automação"]}, {"codigo": "IN-03", "circulo": 3, "nome": "Tornar cada dado confiável: definir, validar, catalogar, classificar e retirar", "dominio": "Dados, indicadores e conhecimento", "classe": "essencial", "onda": 1, "objetivo": "Fazer com que cada dado usado em decisão, indicador ou agente tenha definição, dono, fonte, regra de qualidade, classificação de sigilo e prazo de guarda, esteja no catálogo de dados para pessoas e agentes e saia dele quando o prazo vence ou o tratamento deixa de ser permitido. A Integração conecta a fonte, guarda o dado e controla o acesso; a Governança define o sigilo, as regras de dados pessoais e a regra de guarda.", "frequencia": "Por evento: dado ou fonte nova pedida, queda de qualidade detectada, regra de sigilo alterada ou prazo de guarda vencido", "automacao_nivel": "média", "automacao_motivo": "Validar pela regra, catalogar, publicar e monitorar a qualidade rodam sem pessoa. A ficha é de copiloto: o agente propõe, a pessoa da Inteligência decide a ficha, com a classificação e o prazo de guarda, e o dono confirma. Arquivar ou eliminar é decisão do dono, conferida pela Governança.", "raias": ["Solicitante", "Líder do círculo", "Governança", "Integração", "Inteligência · pessoa", "Inteligência · agente", "Inteligência · automação"]}, {"codigo": "IN-04", "circulo": 3, "nome": "Definir e medir os indicadores e publicar as análises", "dominio": "Dados, indicadores e conhecimento", "classe": "essencial", "onda": 1, "objetivo": "Fazer com que cada alvo e cada decisão recorrente tenham um indicador com definição, dono, fonte, linha de base e cadência, calculado pela mesma ficha para todos e publicado com a análise num painel único. A Inteligência decide a ficha: como se mede e quem pode ver. O dono do resultado confirma a ficha e responde pelo resultado; se não confirma, vale a ficha da Inteligência, com a divergência registrada, e no indicador de alvo decide a Estratégia. É por aqui que a Estratégia confere, antes de aprovar os alvos, se cada um tem indicador, fonte e linha de base.", "frequencia": "A cada período de medição (cadência: medição mensal; revisão dos indicadores anual, junto com os alvos (ES-03)) e por evento: alvos em negociação ou publicados, pedido de indicador, oferta ou empresa nova, número contestado ou revisão dos indicadores. A definição roda por indicador ou por grupo de indicadores do mesmo dono", "automacao_nivel": "alta", "automacao_motivo": "Calcular, comparar, redigir e publicar rodam com agente e automação. Decidir a ficha, validar conclusão nova, concluir a contestação e decidir o que rever são de pessoas.", "raias": ["Estratégia", "Solicitante", "Executivo da empresa", "Líder do círculo", "Inteligência · pessoa", "Inteligência · agente", "Inteligência · automação"]}, {"codigo": "IN-05", "circulo": 3, "nome": "Curar as bases de conhecimento que pessoas e agentes consultam", "dominio": "Dados, indicadores e conhecimento", "classe": "essencial", "onda": 1, "objetivo": "Manter, para cada tema, uma base única, curada, classificada e com dono, em que pessoas e agentes encontram a resposta certa e atual, e fazer cada pergunta sem resposta virar pedido de curadoria. O que já chega aprovado, versionado e classificado por quem publica (padrão, estratégia, método, oferta) é indexado, não revalidado.", "frequencia": "Por evento: conteúdo novo apontado, conteúdo aprovado por quem publica, método ou oferta retirado de uso, lacuna ou conteúdo vencido detectado; e a cada revisão da base (cadência: trimestral)", "automacao_nivel": "alta na estrutura, na publicação e na medição; média na curadoria", "automacao_motivo": "Reunir, estruturar, testar, publicar e medir o uso rodam com agente e automação. Validar o que vale hoje é do dono do tema, e a classificação de sigilo é decisão de pessoa.", "raias": ["Solicitante", "Líder do círculo", "Identidade", "Governança", "Integração", "Inteligência · pessoa", "Inteligência · agente", "Inteligência · automação"]}, {"codigo": "IN-06", "circulo": 3, "nome": "Criar e publicar um método testado, a partir de uma prática ou de uma necessidade", "dominio": "Método e oferta", "classe": "essencial", "onda": 1, "objetivo": "Fazer com que o que funciona na prática, ou o que uma oferta ou capacidade nova exige, vire método escrito, testado em caso real por quem não o descreveu, testado nos agentes, publicado com versão e entregue com critério de sucesso e casos de teste. Quando o método nasce para uma oferta, o caso real é o piloto da IN-07. A Inteligência é a dona do método e avalia, a cada amostra da Governança, se o resultado que ele produz é bom.", "frequencia": "Por evento: prática apontada, recomendação aceita na IN-08, método pedido para oferta, capacidade ou agente, amostra de entregas recebida da Governança; e na data de revisão de cada método", "automacao_nivel": "média", "automacao_motivo": "Estruturar, redigir, medir, avaliar a amostra e montar o kit são de agente; escolher o que vira método, aplicar em caso real, liberar a publicação e decidir manter, rever ou retirar são de pessoas.", "raias": ["Solicitante", "Governança", "Integração", "Pessoa", "Identidade", "Inteligência · pessoa", "Inteligência · agente", "Inteligência · automação"]}, {"codigo": "IN-07", "circulo": 3, "nome": "Desenhar e validar uma oferta com o seu modelo de negócio e prepará-la para o lançamento", "dominio": "Método e oferta", "classe": "essencial", "onda": 2, "objetivo": "Levar uma aposta aprovada no portão de entrada até uma oferta pronta para vender e entregar: enquadramento, solução e método de entrega, modelo de negócio e preço-base, validação com clientes reais e pacote completo. Entre os dois portões, quem decide é a Inteligência; o executivo da empresa, Negócios e a Gestão opinam e sugerem. A Estratégia decide os dois portões. O ajuste de uma oferta em uso, quando cumpre o limite do ajuste (não muda público, promessa nem escopo principal, não reduz o preço-base, não pede capacidade nova nem muda o risco do contrato-modelo), é decidido e feito aqui, sem portão; a revisão que falha em alguma condição volta ao portão de entrada.", "frequencia": "Por evento: aposta aprovada no portão de entrada, decisão da Estratégia sobre aposta devolvida, decisão do portão de lançamento, pedido sobre oferta em uso, aposta ou oferta encerrada, ou empresa que sai do portfólio", "automacao_nivel": "média na preparação, baixa nas decisões", "automacao_motivo": "O agente reúne evidência, monta alternativas, simula o modelo, mede o piloto e redige o pacote. Decidir o caminho do trabalho, o enquadramento, o desenho, o modelo com o preço-base, as condições do piloto, o caminho depois dele, o ajuste de oferta em uso e o pacote é de pessoas da Inteligência, ouvidos o executivo, Negócios e a Gestão; lançar é decisão da Estratégia.", "raias": ["Solicitante", "Estratégia", "Executivo da empresa", "Relações", "Negócios", "Gestão", "Assessoria externa", "Operações", "Integração", "Identidade", "Governança", "Inteligência · pessoa", "Inteligência · agente", "Inteligência · automação"]}, {"codigo": "IN-08", "circulo": 3, "nome": "Aprender com as lições e os resultados e recomendar melhorias", "dominio": "Aprendizado", "classe": "essencial", "onda": 2, "objetivo": "Fazer com que cada lição de aposta, caso, piloto, projeto, cliente ou revisão seja registrada só com o que pode ser dito, cruzada com os indicadores e transformada em recomendação com evidência, entregue a quem pode agir; e conferir se a melhoria aceita foi feita e deu resultado.", "frequencia": "Por evento: cada lição recebida é registrada, e cada ideia devolvida pelo portão de entrada é completada; a cada ciclo de aprendizado (cadência: trimestral, antes da revisão da execução (ES-06)), as lições são cruzadas e viram recomendação", "automacao_nivel": "alta", "automacao_motivo": "Preparar o registro, classificar, cruzar, redigir e conferir são de agente e automação; decidir o que pode ser registrado, escolher o que recomendar e responder à recomendação são de pessoas.", "raias": ["Solicitante", "Líder do círculo", "Governança", "Executivo da empresa", "Inteligência · pessoa", "Inteligência · agente", "Inteligência · automação"]}, {"codigo": "RE-01", "circulo": 4, "nome": "Planejar a geração de demanda do ciclo por público, oferta e canal", "dominio": "Demanda", "classe": "essencial", "onda": 1, "objetivo": "Ter, a cada ciclo, um plano de demanda de cada empresa que diga a que públicos falar, com que ofertas, por quais canais e ações, com que alvo e com que orçamento, a partir da direção, dos alvos, das ofertas no catálogo e do resultado do ciclo anterior, e com o critério de oportunidade qualificada combinado com Negócios. Relações decide o plano, ouvidos Negócios e o executivo; a Gestão confere o orçamento.", "frequencia": "A cada ciclo de demanda (cadência: trimestral) e por evento: oferta aprovada para lançamento, revisão pedida pelo resultado das ações ou resposta da Gestão a pedido de recurso", "automacao_nivel": "média", "automacao_motivo": "Reunir as entradas, comparar com os alvos, propor o plano e somar o custo são de agente e automação; decidir públicos, canais, ações e alvos e combinar o critério com Negócios são de pessoa de Relações.", "raias": ["Estratégia", "Gestão", "Negócios", "Executivo da empresa", "Relações · pessoa", "Relações · agente", "Relações · automação"]}, {"codigo": "RE-02", "circulo": 4, "nome": "Executar as ações de demanda e medir o resultado", "dominio": "Demanda", "classe": "essencial", "onda": 1, "objetivo": "Levar cada ação do plano aos públicos certos, com material conforme os padrões de identidade e só para quem pode ser abordado, captar os contatos com a base legal e medir o resultado de cada ação contra o alvo, e não só pelo alcance; e recolher o material em circulação quando a marca sai de uso ou o material vence.", "frequencia": "Por ação do plano de demanda, no calendário, e por evento: ação fora do plano pedida, marca retirada de uso ou material vencido", "automacao_nivel": "média (alta na execução, média na preparação)", "automacao_motivo": "Redigir, montar o público, publicar, registrar e medir são de agente e automação; aprovar a ação, o material e o público é de pessoa. Preço e condições passam por Negócios; o que fala em nome da empresa, pelo executivo.", "raias": ["Solicitante", "Identidade", "Negócios", "Gestão", "Governança", "Executivo da empresa", "Integração", "Relações · pessoa", "Relações · agente", "Relações · automação"]}, {"codigo": "RE-03", "circulo": 4, "nome": "Qualificar os contatos e entregar a Negócios as oportunidades qualificadas", "dominio": "Demanda", "classe": "essencial", "onda": 1, "objetivo": "Fazer com que cada contato entre na base de relacionamento com a origem e a base legal, receba conteúdo já aprovado pelo interesse que mostra, seja qualificado pelo critério combinado com Negócios e, quando qualificado, chegue a Negócios com o histórico; e manter a base confiável, executando os pedidos dos titulares que a Governança decide.", "frequencia": "Por evento: contato captado, contato de interessado, indicação de cliente, contato de parceiro, interação de contato em nutrição ou pedido de titular; e a cada ciclo de nutrição e revisão da base (cadência: nutrição contínua, por evento; revisão da base semestral)", "automacao_nivel": "alta no registro e na nutrição, baixa na qualificação", "automacao_motivo": "Registrar, juntar duplicados, nutrir, pontuar e entregar rodam com agente e automação; a conversa de qualificação e a aprovação do que se faz na base são de pessoa; a resposta ao titular é decidida pela Governança.", "raias": ["Solicitante", "Governança", "Relações · pessoa", "Relações · agente", "Relações · automação"]}, {"codigo": "RE-04", "circulo": 4, "nome": "Desenhar a experiência do cliente: personas, mapa da jornada e padrões de experiência", "dominio": "Clientes", "classe": "essencial", "onda": 1, "objetivo": "Ter, para cada empresa, uma estratégia de experiência do cliente escrita e validada com clientes: quem são os clientes (personas), por onde passam (mapa da jornada), o que vivem em cada ponto de contato e que padrão de experiência cada etapa tem de cumprir, coerente com os valores e o posicionamento da marca. Operações, Negócios e Integração dizem se conseguem cumprir; Relações decide, ouvidos o executivo e os clientes.", "frequencia": "A cada revisão da experiência (cadência: anual) e por evento: oferta aprovada para lançamento ou lacuna de experiência apontada", "automacao_nivel": "média", "automacao_motivo": "Reunir reclamações, saúde, percepção e indicadores, propor personas e o mapa e conferir com os padrões são de agente; ouvir clientes, desenhar os pontos de contato com Operações e decidir os padrões são de pessoas.", "raias": ["Solicitante", "Cliente", "Estratégia", "Executivo da empresa", "Operações", "Negócios", "Integração", "Identidade", "Relações · pessoa", "Relações · agente", "Relações · automação"]}, {"codigo": "RE-05", "circulo": 4, "nome": "Acompanhar o sucesso de cada cliente, da entrada à renovação, à expansão ou à perda", "dominio": "Clientes", "classe": "essencial", "onda": 1, "objetivo": "Fazer com que cada cliente tenha um plano de sucesso combinado, que a saúde de cada cliente seja medida a cada ciclo, que o risco de perda seja tratado antes da perda, que o resultado seja apresentado ao cliente e que a renovação, a expansão, a indicação ou a lição da perda cheguem a quem age. Negócios negocia a renovação e a expansão e informa o resultado; Operações atende e entrega. Os clientes só são avisados de uma saída quando a data está confirmada.", "frequencia": "Por evento: contrato de cliente assinado, empresa adquirida, sinal de risco, vencimento de contrato, resultado da renovação, decisão de encerrar oferta ou data de saída confirmada; e a cada ciclo de acompanhamento do cliente (cadência: trimestral, por cliente)", "automacao_nivel": "média", "automacao_motivo": "Reunir os dados, calcular a saúde, montar o relatório e apontar oportunidades são de agente e automação; combinar o plano, apresentar o resultado, tratar o risco e decidir o próximo passo são de pessoas de Relações, ouvido o executivo.", "raias": ["Cliente", "Estratégia", "Negócios", "Executivo da empresa", "Identidade", "Relações · pessoa", "Relações · agente", "Relações · automação"]}, {"codigo": "RE-06", "circulo": 4, "nome": "Formar e cuidar de parcerias e relações institucionais e autorizar o uso da marca por terceiros", "dominio": "Parcerias e instituições", "classe": "essencial", "onda": 2, "objetivo": "Fazer cada parceria ou relação institucional nascer de uma avaliação de encaixe, ser formalizada com objetivos, papéis e indicadores, por contrato ou por termo institucional conferido pela Governança e aprovado pelo executivo, ser ativada, acompanhada e, quando deixa de servir, encerrada com ordem; e decidir quem de fora pode usar as marcas, pela regra da Identidade, com a exceção decidida por Relações, ouvida a Identidade, e liberada pela Governança. A parceria acima da alçada sobe aos sócios pela Governança; a que muda o portfólio vai à Estratégia como aposta.", "frequencia": "Por evento: parceria proposta, pedido de uso da marca por terceiro, marca retirada de uso ou encerramento pedido; e na revisão de cada parceria (cadência: semestral, por parceria)", "automacao_nivel": "média", "automacao_motivo": "Registrar, avaliar o parceiro, conferir com a regra e medir o resultado são de agente e automação; negociar, decidir e capacitar são de pessoas; o contrato e a liberação da exceção à regra da marca são da Governança.", "raias": ["Solicitante", "Estratégia", "Identidade", "Parceiro", "Executivo da empresa", "Gestão", "Governança", "Sócios", "Relações · pessoa", "Relações · agente", "Relações · automação"]}, {"codigo": "RE-07", "circulo": 4, "nome": "Comunicar para fora: pauta, conteúdo, imprensa e porta-vozes", "dominio": "Comunicação e reputação", "classe": "essencial", "onda": 1, "objetivo": "Comunicar aos públicos externos, com uma só voz e dentro dos padrões de identidade, os fatos, as mudanças, os lançamentos e os casos que importam, preparar quem fala pela empresa e medir o efeito de cada tema contra o alvo, e não só a exposição. O executivo aprova o que se diz em nome da empresa; a Governança confere o risco jurídico. A comunicação interna é da Gestão.", "frequencia": "A cada ciclo de pauta (cadência: pauta mensal) e por evento: fato a comunicar ou pedido de imprensa", "automacao_nivel": "média", "automacao_motivo": "Reunir fatos, propor a pauta, redigir, conferir, publicar e medir são de agente e automação; decidir a pauta, revisar, aprovar e preparar os porta-vozes são de pessoas.", "raias": ["Solicitante", "Executivo da empresa", "Governança", "Identidade", "Relações · pessoa", "Relações · agente", "Relações · automação"]}, {"codigo": "RE-08", "circulo": 4, "nome": "Monitorar a percepção dos públicos e a reputação e acionar a resposta a crises", "dominio": "Comunicação e reputação", "classe": "essencial", "onda": 1, "objetivo": "Saber, a cada ciclo, como os públicos percebem as marcas, encaminhar cada lacuna a quem pode agir e detectar cedo o que pode virar crise. Relações apura os fatos e leva ao comitê da Governança todo sinal grave ou em dúvida; o comitê declara a crise, decide a posição e o porta-voz e a encerra; Relações redige e publica a comunicação da posição decidida.", "frequencia": "A cada ciclo de monitoramento (cadência: coleta contínua; análise mensal) e por evento: sinal de reputação detectado", "automacao_nivel": "média (alta na coleta, baixa na crise)", "automacao_motivo": "Coletar, classificar, agrupar e publicar são de agente e automação; apurar os fatos, concluir a percepção e comunicar na crise são de pessoas; declarar e encerrar a crise e decidir a posição são da Governança, com o executivo.", "raias": ["Governança", "Executivo da empresa", "Relações · pessoa", "Relações · agente", "Relações · automação"]}, {"codigo": "NE-01", "circulo": 5, "nome": "Manter a tabela de preços, a política comercial e o material de venda de cada empresa", "dominio": "Preço e plano comercial", "classe": "essencial", "onda": 1, "objetivo": "Ter, em cada empresa, uma tabela de preços e uma política comercial vigentes (preço de cada oferta, descontos, condições de pagamento e faixa de desconto de quem vende) que pessoas e agentes usam, a partir do preço-base decidido pela Inteligência e do papel de cada oferta no portfólio-alvo, com o material de venda de cada oferta conforme os padrões de identidade; e parar a venda da oferta encerrada. Negócios decide a tabela e a política, ouvidos o executivo e a Gestão; a faixa de desconto e as condições que mexem nos modelos de contrato são aprovadas pela Governança, dona das alçadas. O preço de tabela fica no preço-base ou acima dele; abaixo, só depois de a Inteligência rever o preço-base.", "frequencia": "Por evento: oferta nova ou preço-base alterado no catálogo, resposta a pedido sobre o preço-base, decisão de encerrar oferta, data de saída, material vencido ou marca retirada; e na revisão da tabela (cadência: semestral, e sempre que um preço-base mudar)", "automacao_nivel": "média", "automacao_motivo": "Reunir as entradas, comparar o preço praticado com o preço-base, propor a tabela, conferir as alçadas e os padrões, preparar o material e publicar são de agente e automação; decidir a tabela e a política é de pessoa de Negócios.", "raias": ["Estratégia", "Inteligência", "Identidade", "Gestão", "Governança", "Executivo da empresa", "Negócios · pessoa", "Negócios · agente", "Negócios · automação"]}, {"codigo": "NE-02", "circulo": 5, "nome": "Planejar as vendas do ciclo e prever a receita", "dominio": "Preço e plano comercial", "classe": "essencial", "onda": 1, "objetivo": "Ter, a cada ciclo, os alvos de venda de cada empresa por oferta e canal, desdobrados dos alvos do ciclo, os clientes-chave com o plano de conta de cada um, e uma previsão de receita e de vendas atualizada a cada período a partir do funil, das propostas, dos contratos, das atas e das renovações, entregue a quem precisa dela para o orçamento, o caixa, a capacidade e a implantação. Negócios decide o desdobramento e a previsão, ouvido o executivo; o desvio contra os alvos vai ao executivo e à Gestão.", "frequencia": "A cada ciclo de vendas e a cada período de previsão (cadências: ciclo de vendas trimestral; previsão mensal) e por evento: alvos do ciclo publicados", "automacao_nivel": "média", "automacao_motivo": "Reunir o funil, as propostas e os contratos, calcular a previsão e comparar com os alvos são de agente e automação; desdobrar os alvos, escolher os clientes-chave e concluir a previsão são de pessoa de Negócios.", "raias": ["Estratégia", "Operações", "Integração", "Executivo da empresa", "Negócios · pessoa", "Negócios · agente", "Negócios · automação"]}, {"codigo": "NE-03", "circulo": 5, "nome": "Aceitar a oportunidade, desenhar a solução e fazer a proposta", "dominio": "Venda", "classe": "essencial", "onda": 1, "objetivo": "Fazer cada oportunidade qualificada receber aceite ou devolução com o motivo no prazo combinado com Relações e, aceita, virar uma proposta com escopo que a operação e a implantação conseguem entregar, preço pela tabela, concessão dentro da alçada, conforme os padrões de identidade e no modelo da Governança. A oportunidade de parceiro ou de oferta conjunta já aceita na NE-07 entra direto no escopo, que é confirmado com o cliente. O que foge do catálogo vai à Inteligência ou à Estratégia, e a resposta da Inteligência retoma a proposta; o contato que chega direto a Negócios vai a Relações para ser qualificado.", "frequencia": "Por evento: oportunidade qualificada, oportunidade sem resposta no prazo, oportunidade de parceiro ou de oferta conjunta, mudança de escopo pedida na negociação, resposta da Inteligência ou pedido que chega direto do cliente", "automacao_nivel": "média", "automacao_motivo": "Registrar, conferir com o critério, montar o escopo, calcular o preço, redigir, conferir os padrões e enviar são de agente e automação; aceitar, conversar com o cliente, decidir o escopo e aprovar a proposta são de pessoa de Negócios.", "raias": ["Relações", "Inteligência", "Cliente", "Operações", "Integração", "Identidade", "Governança", "Executivo da empresa", "Sócios", "Negócios · pessoa", "Negócios · agente", "Negócios · automação"]}, {"codigo": "NE-04", "circulo": 5, "nome": "Negociar e fechar o contrato com o cliente", "dominio": "Venda", "classe": "essencial", "onda": 1, "objetivo": "Fazer cada proposta aceita ou em negociação terminar em contrato assinado no modelo da Governança, com as concessões dentro das alçadas, ou em perda registrada com o motivo; e passar o contrato a quem implanta, entrega, fatura e acompanha o cliente. Contratos e aditivos seguem o modelo da Governança, que já traz os padrões de identidade. O executivo assina pela empresa; a Governança revisa o que foge do modelo, confere os poderes de quem assina e guarda.", "frequencia": "Por evento: proposta aceita ou em negociação", "automacao_nivel": "média", "automacao_motivo": "Simular concessões, redigir o contrato no modelo, registrar e avisar são de agente e automação; negociar, aprovar concessões e conferir o contrato são de pessoas; assinar é do executivo.", "raias": ["Cliente", "Governança", "Executivo da empresa", "Sócios", "Negócios · pessoa", "Negócios · agente", "Negócios · automação"]}, {"codigo": "NE-05", "circulo": 5, "nome": "Disputar licitações e contratar com o setor público", "dominio": "Venda", "classe": "essencial", "onda": 1, "objetivo": "Decidir em cada edital se a empresa participa, montar a proposta e os documentos de habilitação nas regras do edital, disputar, acompanhar o julgamento, a habilitação, os recursos e a homologação e, ganhando, assinar o contrato ou a ata de registro de preços; responder ao pedido de cotação para pesquisa de preços; e responder ao órgão não participante que pede para aderir à ata. Negócios decide participar e recorrer, ouvidos o executivo e a Governança; a Governança confere a habilitação e conduz esclarecimentos, impugnações, recursos e contrarrazões; o executivo assina. Prazos e regras de impugnação, recurso, convocação e adesão seguem a lei e o edital e não foram conferidos neste desenho.", "frequencia": "Por evento: edital ou pedido de cotação encontrado ou recebido, resultado da disputa, convocação para assinar, ou pedido de adesão à ata", "automacao_nivel": "média", "automacao_motivo": "Monitorar editais, conferir exigências, calcular o preço, montar os documentos, enviar e registrar são de agente e automação; decidir participar, dar lances, decidir recorrer e decidir a adesão são de pessoa de Negócios; esclarecer, impugnar e recorrer são da Governança; assinar é do executivo.", "raias": ["Cliente", "Operações", "Identidade", "Governança", "Executivo da empresa", "Sócios", "Negócios · pessoa", "Negócios · agente", "Negócios · automação"]}, {"codigo": "NE-06", "circulo": 5, "nome": "Cuidar dos contratos dos clientes: renovar, ampliar, aditar e encerrar", "dominio": "Contas e contratos", "classe": "essencial", "onda": 1, "objetivo": "Fazer cada contrato de cliente ser renovado, ampliado ou aditado no tempo certo, com as concessões dentro das alçadas e com o escopo novo confirmado por Operações e pela Integração, a partir da oportunidade que Relações aponta, do pedido do cliente e do plano de conta; tratar o pedido de cancelamento com uma negociação de retenção e, perdido o cliente ou vencida a vigência sem renovação, formalizar o fim do contrato e avisar quem entrega, implanta e fatura; atender a contratação de órgão participante pela ata; e, quando uma oferta é encerrada ou uma empresa sai, encerrar ou transferir os contratos pelo plano de saída coordenado pela Integração. O vencimento próximo só avisa Relações, que decide se abre a renovação. Relações acompanha o sucesso do cliente; Negócios negocia e formaliza; o executivo assina.", "frequencia": "Por evento: oportunidade de renovação ou de expansão, vencimento próximo, pedido do cliente, contratação pela ata, pedido de cancelamento, decisão de encerrar oferta, data de saída ou mandato", "automacao_nivel": "média", "automacao_motivo": "Vigiar vencimentos e saldos, preparar a proposta de renovação, redigir o aditivo, registrar e avisar são de agente e automação; negociar, decidir concessões, conferir e executar a parte de Negócios do plano de saída são de pessoas; assinar é do executivo.", "raias": ["Relações", "Estratégia", "Cliente", "Operações", "Integração", "Identidade", "Governança", "Executivo da empresa", "Sócios", "Negócios · pessoa", "Negócios · agente", "Negócios · automação"]}, {"codigo": "NE-07", "circulo": 5, "nome": "Vender com parceiros e em oferta conjunta entre as empresas", "dominio": "Venda conjunta", "classe": "essencial", "onda": 2, "objetivo": "Fazer a oportunidade trazida por um parceiro de venda ativo ser conferida com o critério combinado com Relações e com o funil e, aceita, chegar à proposta sem conflito; montar com outra empresa do Ecossistema a oferta conjunta quando o cliente de uma tem um problema que a outra resolve, com a divisão de receita e de responsabilidade decidida pelos executivos das duas empresas (exceção à regra de que o executivo opina, porque mexe no resultado de duas empresas) e formalizada pela Governança antes da proposta; e medir a venda com parceiros e conjunta. Relações forma, ativa e acompanha o parceiro; Negócios vende com ele.", "frequencia": "Por evento: oportunidade de parceiro ou oportunidade cruzada entre empresas; e na revisão da venda com parceiros (cadência: semestral)", "automacao_nivel": "média", "automacao_motivo": "Registrar, conferir o funil e o parceiro, calcular o preço conjunto e medir são de agente e automação; aceitar a oportunidade do parceiro, desenhar a oferta conjunta e concluir a revisão são de pessoa de Negócios; a divisão é dos executivos.", "raias": ["Parceiro", "Executivo da empresa", "Gestão", "Governança", "Negócios · pessoa", "Negócios · agente", "Negócios · automação"]}, {"codigo": "IT-01", "circulo": 6, "nome": "Gerir a carteira de projetos do Ecossistema e das empresas", "dominio": "Projetos e implantação", "classe": "essencial", "onda": 1, "objetivo": "Fazer cada projeto, interno ou de cliente, entrar numa carteira única com objetivo, dono, prazo, custo e empresa; ser priorizado contra a capacidade; ser acompanhado com o desvio apontado a tempo; e ser encerrado com a entrega conferida e as lições registradas. O executivo decide a prioridade dos projetos da sua empresa; a Integração decide a dos projetos corporativos e o método; o conflito de capacidade entre empresas sobe à Estratégia. A Integração informa a situação da carteira à Estratégia e à Gestão.", "frequencia": "Por evento: iniciativa aprovada, decisão de portão, oferta para lançamento, implantação de cliente, capacidade nova, plano de saída, aposta devolvida ou encerrada; e a cada ciclo de acompanhamento (cadência: mensal)", "automacao_nivel": "média", "automacao_motivo": "Registrar, estimar, simular a carga, coletar a situação e apontar desvios são de agente e automação; definir objetivo e dono, priorizar os projetos corporativos e decidir a correção são de pessoa da Integração; a prioridade dos projetos de cada empresa é do executivo.", "raias": ["Estratégia", "Inteligência", "Executivo da empresa", "Integração · pessoa", "Integração · agente", "Integração · automação"]}, {"codigo": "IT-02", "circulo": 6, "nome": "Implantar o cliente, do contrato assinado à operação", "dominio": "Projetos e implantação", "classe": "essencial", "onda": 1, "objetivo": "Fazer cada contrato assinado virar um cliente implantado e aceito, com um plano combinado com o cliente e com Operações, ambiente, acessos, pessoas e materiais prontos, e passado a Operações para a entrega recorrente. A Integração coordena; Operações confirma a capacidade e assume a entrega; a Gestão compra o que falta; o cliente aceita.", "frequencia": "Por evento: contrato de cliente assinado ou com escopo novo", "automacao_nivel": "média", "automacao_motivo": "Montar o cronograma e os riscos, configurar acessos, conferir requisitos, os padrões e acompanhar são de agente e automação; combinar o plano com o cliente, implantar e conferir o aceite são de pessoas.", "raias": ["Negócios", "Cliente", "Operações", "Gestão", "Identidade", "Executivo da empresa", "Integração · pessoa", "Integração · agente", "Integração · automação"]}, {"codigo": "IT-03", "circulo": 6, "nome": "Coordenar o lançamento da oferta aprovada", "dominio": "Projetos e implantação", "classe": "essencial", "onda": 1, "objetivo": "Fazer cada oferta aprovada no portão de lançamento chegar ao mercado com um plano único: quem faz o quê em Relações, Negócios, Operações, Gestão e Governança, com marcos e riscos, a prontidão conferida antes de lançar e os primeiros resultados acompanhados. A Integração coordena com o executivo da empresa; cada círculo executa a sua parte.", "frequencia": "Por evento: oferta aprovada para lançamento", "automacao_nivel": "média", "automacao_motivo": "Montar o plano, coletar a prontidão e acompanhar os primeiros indicadores são de agente e automação; fechar o plano e decidir lançar são de pessoa da Integração, ouvido o executivo.", "raias": ["Estratégia", "Relações", "Negócios", "Operações", "Gestão", "Governança", "Executivo da empresa", "Integração · pessoa", "Integração · agente", "Integração · automação"]}, {"codigo": "IT-04", "circulo": 6, "nome": "Montar e coordenar o plano de saída de oferta ou de empresa", "dominio": "Projetos e implantação", "classe": "essencial", "onda": 1, "objetivo": "Fazer cada oferta encerrada ou empresa que sai do portfólio ter um plano de saída de clientes, contratos, pessoas, sistemas e dados, montado com os círculos que executam e entregue à Estratégia, que decide a data; e, com a data confirmada, coordenar a execução até a conclusão, apontando as pendências. No mandato de criação ou de aquisição, a Integração abre na carteira o projeto de ligar a empresa aos círculos. Cada círculo executa a sua parte; a Integração coordena.", "frequencia": "Por evento: pedido de plano de saída, mandato de empresa, data de saída confirmada ou pendência apontada", "automacao_nivel": "média", "automacao_motivo": "Levantar o que é afetado e acompanhar são de agente e automação; montar o plano com os círculos, fechar o plano e coordenar a execução são de pessoa da Integração.", "raias": ["Estratégia", "Relações", "Negócios", "Operações", "Gestão", "Governança", "Executivo da empresa", "Integração · pessoa", "Integração · agente", "Integração · automação"]}, {"codigo": "IT-05", "circulo": 6, "nome": "Atender pedidos de capacidade e de serviço e manter o catálogo de capacidades", "dominio": "Capacidades e agentes", "classe": "essencial", "onda": 1, "objetivo": "Fazer cada pedido de serviço de uma empresa a um círculo chegar ao círculo dono da capacidade com um acordo de serviço, e cada necessidade de capacidade nova ou mudada virar uma ficha com método, conhecimento, executor (pessoa, agente, automação ou assessoria), ferramentas, acordo de serviço, indicador e alçada, aceita pelo líder do círculo dono e publicada no catálogo, ligada às jornadas e às tarefas. A Inteligência dá o método e o conhecimento; a Governança define a alçada; o líder do círculo dono aceita a capacidade.", "frequencia": "Por evento: pedido de serviço, necessidade de capacidade, capacidades pedidas por oferta, método publicado, retirado ou recusado; e na revisão do catálogo (cadência: trimestral)", "automacao_nivel": "alta", "automacao_motivo": "Registrar, identificar a capacidade, encaminhar, propor a ficha e versionar o catálogo são de agente e automação; decidir a ficha e o executor é de pessoa da Integração; aceitar a capacidade é do líder do círculo dono; a alçada é da Governança.", "raias": ["Solicitante", "Executivo da empresa", "Inteligência", "Governança", "Líder do círculo", "Integração · pessoa", "Integração · agente", "Integração · automação"]}, {"codigo": "IT-06", "circulo": 6, "nome": "Cuidar dos agentes e automações: montar, testar, liberar, monitorar e corrigir", "dominio": "Capacidades e agentes", "classe": "essencial", "onda": 1, "objetivo": "Fazer cada agente ou automação ser montado pela ficha da capacidade, com o método, o conhecimento, os padrões de identidade e a alçada; passar nos casos de teste da Inteligência e da Identidade antes de entrar em uso; ser aceito pelo líder do círculo dono; e ser monitorado em uso, com o desvio corrigido, suspenso quando sai da alçada e retirado quando o método, a base ou a marca saem de uso. A Inteligência diz o que o agente precisa saber e mede se ele acertou; a Integração monta, testa, libera e mantém; a Governança define a alçada e audita.", "frequencia": "Por evento: pedido de montagem ou de mudança, método, base, padrão ou marca alterados, falha ou desvio detectado; e a cada ciclo de monitoramento (cadência: mensal)", "automacao_nivel": "média", "automacao_motivo": "Montar, rodar os casos de teste, medir o acerto e monitorar são de agente e automação; decidir a arquitetura, julgar os casos de fronteira, liberar e decidir a correção são de pessoa da Integração; aceitar o agente é do líder do círculo dono; a alçada é da Governança.", "raias": ["Inteligência", "Identidade", "Governança", "Líder do círculo", "Integração · pessoa", "Integração · agente", "Integração · automação"]}, {"codigo": "IT-07", "circulo": 6, "nome": "Operar a tecnologia: pedidos, incidentes, acessos, mudanças e fornecedores", "dominio": "Tecnologia e jornadas", "classe": "essencial", "onda": 1, "objetivo": "Fazer cada pedido, incidente ou risco de tecnologia ser resolvido no prazo; cada acesso a dados e sistemas ser dado e retirado pela classificação do dado e pelo pedido; cada mudança em sistema ser testada, aprovada e reversível; cada incidente de segurança ou de dados pessoais ser tratado com a Governança; e cada fornecedor e licença de tecnologia ser escolhido, contratado e controlado com a Gestão e a Governança. A Integração opera e protege; a Governança define a política e verifica; a Gestão compra e paga.", "frequencia": "Por evento: pedido, incidente ou risco de tecnologia, contrato de cliente encerrado, pedido de acesso ou de retirada vindo de outra jornada, pedido de fornecedor ou licença, renovação próxima", "automacao_nivel": "média", "automacao_motivo": "Receber, classificar, resolver o que é conhecido, conceder e retirar acessos pela regra, testar e implantar mudanças padrão e registrar são de agente e automação; resolver o caso novo, aprovar mudança e escolher fornecedor são de pessoa da Integração.", "raias": ["Solicitante", "Negócios", "Governança", "Gestão", "Integração · pessoa", "Integração · agente", "Integração · automação"]}, {"codigo": "IT-08", "circulo": 6, "nome": "Medir e redesenhar as jornadas ponta a ponta e manter o catálogo de jornadas", "dominio": "Tecnologia e jornadas", "classe": "essencial", "onda": 2, "objetivo": "Fazer cada jornada ponta a ponta ser medida, ter o gargalo achado com evidência, ser redesenhada com o círculo dono e com os círculos por onde passa, ter o redesenho decidido pelo líder do círculo dono e conferido pela Governança quando mexe em alçada, regra ou contrato, ser implantada e ter o ganho conferido; e manter o catálogo de jornadas, etapas e tarefas íntegro e versionado. A Integração mede, propõe e implanta; o líder do círculo dono decide.", "frequencia": "A cada ciclo de melhoria (cadência: trimestral) e por evento: recomendação de melhoria, lacuna de execução ou mudança aprovada em outra jornada", "automacao_nivel": "alta", "automacao_motivo": "Medir, achar o gargalo, versionar o catálogo e conferir o ganho são de agente e automação; propor o redesenho é de pessoa da Integração; decidir é do líder do círculo dono.", "raias": ["Inteligência", "Identidade", "Governança", "Líder do círculo", "Integração · pessoa", "Integração · agente", "Integração · automação"]}, {"codigo": "OP-01", "circulo": 7, "nome": "Planejar a capacidade de entrega de cada oferta e cobrir as faltas", "dominio": "Capacidade e entrega", "classe": "essencial", "onda": 1, "objetivo": "Fazer a capacidade de pessoas, agentes, parceiros, materiais e ativos acompanhar a demanda prevista: cada oferta lançada, mudada ou retirada, cada previsão de vendas, ata, parceria e mandato traduzidos em trabalho; cada falta coberta (remanejar, contratar, usar parceiro, automatizar ou recusar) por decisão de Operações ou, acima da alçada, do executivo; e um plano publicado, usado para confirmar propostas, implantações e lançamentos. Operações planeja e decide; a Gestão contrata e compra; a Integração cria a capacidade que falta.", "frequencia": "A cada ciclo de planejamento (cadência: trimestral) e por evento: previsão de vendas, oferta aprovada, lançada ou retirada, parceria ativa ou mandato de empresa", "automacao_nivel": "alta", "automacao_motivo": "Reunir, traduzir a demanda em trabalho, comparar com a capacidade e pedir recursos são de agente e automação; decidir o plano é de pessoa de Operações; o que passa da alçada é do executivo.", "raias": ["Negócios", "Executivo da empresa", "Operações · pessoa", "Operações · agente", "Operações · automação"]}, {"codigo": "OP-02", "circulo": 7, "nome": "Entregar o serviço a cada cliente, ciclo a ciclo", "dominio": "Capacidade e entrega", "classe": "essencial", "onda": 1, "objetivo": "Fazer cada cliente implantado ter um plano de entrega com escopo, nível de serviço, equipe, agentes e contatos; cada entrega feita pelo método da oferta, conferida contra o escopo e o padrão e aceita pelo cliente; cada ciclo confirmado conforme o contrato, com a medição dos níveis de serviço, e passado à Gestão para faturar; cada impasse sobre a entrega virar reclamação tratada; e cada plano de recuperação de Relações virar ajuste do plano de entrega. Operações entrega; o cliente aceita; a Gestão fatura.", "frequencia": "Por cliente: ao receber o cliente implantado (novo, renovado ou ampliado) ou o plano de recuperação, e a cada ciclo de entrega do contrato (cadência do contrato)", "automacao_nivel": "alta", "automacao_motivo": "Programar, conferir, confirmar e registrar são de agente e automação; a entrega é de pessoa ou de agente, conforme o método da oferta; aprovar o plano e corrigir a entrega são de pessoa de Operações.", "raias": ["Integração", "Relações", "Cliente", "Operações · pessoa", "Operações · agente", "Operações · automação"]}, {"codigo": "OP-08", "circulo": 7, "nome": "Encerrar as entregas no fim do contrato ou na saída da oferta ou da empresa", "dominio": "Capacidade e entrega", "classe": "essencial", "onda": 1, "objetivo": "Fazer cada contrato encerrado e cada saída de oferta ou de empresa virar um fim de entregas planejado: no fim do contrato, de imediato; na saída, preparado pelo plano de saída da Integração e executado na data confirmada pela Estratégia. As entregas são concluídas ou transferidas na transição combinada por Relações; o último ciclo é passado a faturar; os dados e materiais do cliente são devolvidos ou eliminados, com aprovação de pessoa, guardado só o que a lei ou o contrato mandam guardar; os recursos são liberados à Gestão; e a conclusão vai à Integração e as lições à Inteligência.", "frequencia": "Por evento: contrato encerrado, plano de saída, data de saída confirmada ou mandato de empresa", "automacao_nivel": "média", "automacao_motivo": "Listar o que está em curso, executar a devolução ou a eliminação aprovada, liberar recursos e arquivar são de agente e automação; planejar, concluir as entregas e aprovar o destino dos dados são de pessoa de Operações; o cliente confirma.", "raias": ["Negócios", "Integração", "Estratégia", "Cliente", "Operações · pessoa", "Operações · agente", "Operações · automação"]}, {"codigo": "OP-03", "circulo": 7, "nome": "Atender o cliente: pedidos, dúvidas e problemas, do contato à solução", "dominio": "Atendimento e qualidade", "classe": "essencial", "onda": 1, "objetivo": "Fazer cada contato de cliente ser registrado, classificado pelo nível de serviço que vale, resolvido pela base de conhecimento ou por pessoa e respondido; cada problema de tecnologia ir à Integração; cada caso sem padrão ir à Identidade e cada dúvida sobre a oferta em uso à Inteligência; cada reclamação, e cada caso que não se resolve, ir ao tratamento de reclamações; cada pedido comercial ir a Negócios; e cada atendimento deixar registro e o conteúdo que faltou. Operações atende; Negócios trata o pedido comercial.", "frequencia": "Por evento: cada contato do cliente, em qualquer canal", "automacao_nivel": "alta", "automacao_motivo": "Registrar, classificar, responder o que a base cobre, consultar e registrar são de agente e automação; resolver o caso que o agente não resolve é de pessoa de Operações, só quando a resposta não resolveu.", "raias": ["Cliente", "Negócios", "Operações · pessoa", "Operações · agente", "Operações · automação"]}, {"codigo": "OP-04", "circulo": 7, "nome": "Tratar reclamações e incidentes de clientes e corrigir a causa", "dominio": "Atendimento e qualidade", "classe": "essencial", "onda": 1, "objetivo": "Fazer cada reclamação ou incidente de cliente ser registrado com o prazo de resposta, classificado pela gravidade e pelo risco legal, investigado até a causa e resolvido por decisão de Operações ou, acima da alçada, do executivo; quando o cliente é consumidor, oferecidas as alternativas da lei; a resposta, inclusive a de improcedência, dada por escrito e registrada; o caso sem acordo encerrado com a informação de onde mais o cliente pode recorrer; e cada causa virar ação corretiva, pedido de ajuste da oferta ou lacuna de experiência. Operações trata; a Governança avalia o dever de comunicar a autoridade; Relações recebe a reclamação com a causa.", "frequencia": "Por evento: reclamação aberta no atendimento ou na entrega, ou recebida de outro canal", "automacao_nivel": "média", "automacao_motivo": "Registrar, classificar, confirmar o recebimento, propor a solução, analisar a causa e registrar são de agente e automação; conferir a classificação, decidir a solução e aplicá-la são de pessoa de Operações; o que passa da alçada é do executivo, com a avaliação da Governança.", "raias": ["Solicitante", "Governança", "Executivo da empresa", "Operações · pessoa", "Operações · agente", "Operações · automação"]}, {"codigo": "OP-05", "circulo": 7, "nome": "Garantir a qualidade e os níveis de serviço: padrões, medida e ação corretiva", "dominio": "Atendimento e qualidade", "classe": "essencial", "onda": 1, "objetivo": "Fazer os padrões de experiência de Relações e o método de cada oferta virarem procedimentos e níveis de serviço por oferta e por segmento de cliente; a qualidade e os níveis de serviço serem medidos; cada não conformidade, reclamação recorrente ou lacuna apontada ter a causa achada e uma ação corretiva decidida, implantada e conferida; a causa que Operações não consegue eliminar ir ao executivo; e o padrão que a operação não consegue cumprir voltar a Relações como lacuna. Operações define e mede; Relações define a experiência; a Inteligência publica o painel.", "frequencia": "A cada ciclo de avaliação da qualidade (cadência: mensal) e por evento: padrão ou oferta nova ou mudada, ação corretiva aberta, lacuna de execução ou de percepção", "automacao_nivel": "alta", "automacao_motivo": "Traduzir padrões, medir, comparar com os alvos, analisar a causa e registrar são de agente e automação; decidir procedimentos, níveis de serviço e ação corretiva e implantá-la são de pessoa de Operações.", "raias": ["Executivo da empresa", "Operações · pessoa", "Operações · agente", "Operações · automação"]}, {"codigo": "OP-06", "circulo": 7, "nome": "Abastecer e entregar o produto físico: demanda, materiais, produção, estoque e transporte", "dominio": "Produto físico", "classe": "recomendada", "onda": 2, "objetivo": "Onde a oferta tem produto físico, fazer a previsão de vendas e os contratos virarem plano de produção e de materiais; cada material ser pedido à Gestão, recebido e inspecionado, e o não conforme recusado e reposto; cada produto ser produzido ou montado, testado pelo procedimento padrão e registrado por lote; cada defeito com risco à saúde ou à segurança ir ao pós-venda; e cada pedido ser guardado, expedido, transportado, recebido pelo cliente e passado à Gestão para faturar. Operações planeja, produz e entrega; a Gestão compra.", "frequencia": "A cada ciclo de planejamento de suprimentos (cadência: mensal) e por contrato com produto assinado", "automacao_nivel": "média", "automacao_motivo": "Prever, calcular a necessidade, pedir a compra, programar, testar, controlar o estoque, acompanhar o transporte e registrar são de agente e automação; decidir o plano, receber materiais, produzir e expedir são de pessoa de Operações.", "raias": ["Negócios", "Gestão", "Cliente", "Operações · pessoa", "Operações · agente", "Operações · automação"]}, {"codigo": "OP-07", "circulo": 7, "nome": "Prestar o pós-venda do produto: devolução, garantia, assistência e recall", "dominio": "Produto físico", "classe": "recomendada", "onda": 2, "objetivo": "Onde a oferta tem produto físico, fazer cada pedido de devolução, garantia ou assistência ser conferido contra os termos e os prazos legais, contados pelo tipo de vício; cada vício ser sanado no prazo e, quando não for, resolvido pela escolha do cliente consumidor (troca, devolução do valor ou abatimento); cada defeito com risco à saúde ou à segurança, venha do cliente ou da própria operação, ser comunicado de imediato à autoridade e aos consumidores e virar proposta de recall decidida pelo executivo, acompanhada e encerrada; e cada causa recorrente virar ação corretiva ou cobrança do fornecedor. Operações atende e propõe; a Governança comunica a autoridade; Relações comunica o público; o executivo decide o recall.", "frequencia": "Por evento: pedido de devolução, garantia ou assistência; defeito com risco à saúde ou à segurança", "automacao_nivel": "média", "automacao_motivo": "Registrar, conferir os termos e prazos, avaliar o risco, acompanhar o recall e analisar a recorrência são de agente e automação; investigar, sanar e cumprir a escolha do cliente são de pessoa de Operações; o recall é do executivo.", "raias": ["Cliente", "Governança", "Executivo da empresa", "Operações · pessoa", "Operações · agente", "Operações · automação"]}, {"codigo": "GE-01", "circulo": 8, "nome": "Desdobrar o orçamento aprovado e controlar as mudanças de recurso", "dominio": "Planejamento e controle", "classe": "essencial", "onda": 1, "objetivo": "Fazer o orçamento aprovado pelos sócios ser desdobrado por empresa, círculo, oferta, aposta e conta, com um dono por linha; os planos de demanda, de vendas, de capacidade e de lançamento caberem nele ou terem a diferença apontada; cada pedido de recurso, liberação, congelamento ou devolução ser decidido na alçada, pela Gestão ou, acima dela, pelo executivo (recurso da empresa), pelo Administrador do IMTS.OS (recurso dos círculos compartilhados) ou pelos sócios (aumento do total aprovado); e o orçamento vigente ser publicado a quem executa. Os sócios aprovam; a Gestão desdobra e controla; a realocação entre empresas fica na revisão do portfólio da Estratégia.", "frequencia": "A cada ciclo de orçamento, depois da aprovação dos sócios, e por evento: pedido de recurso, aposta aprovada, devolvida ou encerrada, projeto suspenso, recurso liberado", "automacao_nivel": "média", "automacao_motivo": "Desdobrar, conferir os planos com o orçamento, calcular o efeito e publicar são de agente e automação; fechar o desdobramento e decidir dentro da alçada são de pessoa da Gestão; acima da alçada, do executivo, do Administrador do IMTS.OS ou dos sócios.", "raias": ["Estratégia", "Sócios", "Administrador do IMTS.OS", "Executivo da empresa", "Gestão · pessoa", "Gestão · agente", "Gestão · automação"]}, {"codigo": "GE-02", "circulo": 8, "nome": "Rodar o ritual de acompanhamento dos alvos e cobrar as ações", "dominio": "Planejamento e controle", "classe": "essencial", "onda": 1, "objetivo": "Fazer cada período ter os resultados reunidos contra os alvos, com a execução do orçamento, os desvios e as causas prováveis; cada desvio ser discutido com o dono no ritual e ter uma ação com dono e prazo, decidida na alçada; cada pedido de plano de correção e cada correção publicada pela Estratégia entrar na pauta; e cada ação ser cobrada até concluir, com o atraso levado ao executivo. A Gestão roda o ritual; os donos decidem as ações; a Estratégia decide a correção de rumo.", "frequencia": "No calendário do método de estratégia (cadência: mensal) e por evento: pedido de plano de correção", "automacao_nivel": "alta", "automacao_motivo": "Reunir, apontar desvios, registrar e cobrar são de agente e automação; conduzir o ritual é de pessoa da Gestão; propor e decidir as ações é dos líderes e do executivo.", "raias": ["Estratégia", "Líder do círculo", "Executivo da empresa", "Gestão · pessoa", "Gestão · agente", "Gestão · automação"]}, {"codigo": "GE-03", "circulo": 8, "nome": "Faturar os clientes e receber e cobrar o que é devido", "dominio": "Finanças", "classe": "essencial", "onda": 1, "objetivo": "Fazer cada cliente ter o cadastro de cobrança conforme o contrato, a tabela, a ata e a divisão da oferta conjunta; cada entrega confirmada por Operações virar fatura, com a medição dos níveis de serviço e os créditos aprovados; cada recebimento ser conciliado e cada atraso cobrado, com a negociação acima do limite decidida pela Gestão, ouvido o executivo, e a suspensão das novas entregas do cliente privado na segunda fatura vencida decidida pelo executivo; o reembolso pago só depois de aprovado pelo líder do círculo; e a situação de faturas e pagamentos de cada cliente ir a Relações e a Negócios. Operações confirma a entrega; a Gestão fatura e recebe.", "frequencia": "Por evento: contrato, oferta ou cliente novo, mudado ou encerrado; entregas confirmadas; vencimento de fatura", "automacao_nivel": "alta", "automacao_motivo": "Cadastrar, calcular, emitir, conciliar, cobrar e informar são de agente e automação; aprovar a fatura fora do padrão, decidir a negociação do atraso e propor a suspensão são de pessoa da Gestão; aprovar o reembolso é do líder do círculo; decidir a suspensão é do executivo.", "raias": ["Negócios", "Operações", "Executivo da empresa", "Líder do círculo", "Gestão · pessoa", "Gestão · agente", "Gestão · automação"]}, {"codigo": "GE-04", "circulo": 8, "nome": "Comprar e pagar: do pedido de compra ao fornecedor e ao parceiro pagos", "dominio": "Finanças", "classe": "essencial", "onda": 1, "objetivo": "Fazer cada pedido de compra ser conferido contra o orçamento e a alçada; cada fornecedor ser escolhido por preço, prazo, qualidade e risco, com o contrato revisado e guardado pela Governança; cada compra ser recebida e conferida por quem pediu; cada fatura de fornecedor ser conferida com o pedido e o recebimento e paga com a aprovação do líder do círculo, que não é quem escolhe o fornecedor; cada fornecedor ser avaliado e cobrado pelas falhas; a remuneração de cada parceiro ser apurada pelo contrato e paga; e os contratos de fornecedor serem encerrados ou transferidos na saída. Quem precisa pede, inclusive a Integração nas compras da implantação e de tecnologia; a Gestão compra e paga; a Governança revisa e guarda o contrato.", "frequencia": "Por evento: pedido de compra, fatura de fornecedor, falha ou desempenho de fornecedor apontado", "automacao_nivel": "média", "automacao_motivo": "Conferir orçamento e alçada, cotar, emitir o pedido, registrar o recebimento, conferir a fatura e pagar são de agente e automação; escolher o fornecedor, resolver divergências e cobrar a falha são de pessoa da Gestão; aprovar o pagamento é do líder do círculo.", "raias": ["Solicitante", "Estratégia", "Governança", "Sócios", "Executivo da empresa", "Líder do círculo", "Gestão · pessoa", "Gestão · agente", "Gestão · automação"]}, {"codigo": "GE-05", "circulo": 8, "nome": "Gerir o caixa, fechar as contas e os impostos e prestar contas", "dominio": "Finanças", "classe": "essencial", "onda": 1, "objetivo": "Fazer cada recebimento e pagamento ser registrado e conciliado; o caixa ser projetado com a previsão de receita, os compromissos e o orçamento e informado à Estratégia; cada período ser fechado por empresa e consolidado, com os impostos apurados e as obrigações entregues, o resultado, os custos e margens e a execução do orçamento publicados; e cada aporte, distribuição ou mudança de contas decidido pelos sócios ou pelo mandato ser executado com dupla aprovação: a Gestão prepara e confere; o líder do círculo, o executivo ou o Administrador do IMTS.OS aprovam; as contas e os poderes bancários são conferidos pela Governança. Os sócios decidem; a Governança recebe as demonstrações para prestar contas.", "frequencia": "A cada período de fechamento (cadência: fechamento mensal; balanço anual) e por evento: decisão de alocação ou de destino do resultado, mandato ou mudança no portfólio", "automacao_nivel": "média", "automacao_motivo": "Registrar, conciliar, projetar, fechar e apurar são de agente e automação; conferir o fechamento e os impostos e conferir a execução de aportes e distribuições são de pessoa da Gestão; aprovar o fechamento e os impostos é do líder do círculo; aprovar a execução é do líder do círculo ou, acima da alçada, do executivo; as contas do IMTS.OS, do Administrador; a conferência das contas, da Governança.", "raias": ["Estratégia", "Governança", "Administrador do IMTS.OS", "Executivo da empresa", "Líder do círculo", "Gestão · pessoa", "Gestão · agente", "Gestão · automação"]}, {"codigo": "GE-06", "circulo": 8, "nome": "Aplicar o rateio do custo dos círculos entre as empresas", "dominio": "Finanças", "classe": "essencial", "onda": 1, "objetivo": "Fazer o custo dos círculos do Ecossistema central ser repartido entre as empresas pelo critério definido pela Governança com a Estratégia: custo e uso apurados, critério aplicado, rateio conferido, aberto à opinião de cada executivo, publicado e lançado nas contas; e cada contestação do critério ir à Governança. A Governança define o critério; a Gestão aplica.", "frequencia": "A cada período de fechamento (cadência: mensal, com o fechamento)", "automacao_nivel": "média", "automacao_motivo": "Reunir o custo e o uso, aplicar o critério, publicar e lançar são de agente e automação; conferir e tratar a contestação são de pessoa da Gestão; o executivo opina.", "raias": ["Executivo da empresa", "Gestão · pessoa", "Gestão · agente", "Gestão · automação"]}, {"codigo": "GE-07", "circulo": 8, "nome": "Prover pessoas: vaga, seleção, contratação, movimentação e desligamento", "dominio": "Pessoas e cultura", "classe": "essencial", "onda": 1, "objetivo": "Fazer cada vaga, movimentação ou desligamento pedido pelo líder, pelo plano de capacidade ou pelo mandato ser conferido contra o orçamento, o perfil do kit de cultura e a alçada; cada vaga ser preenchida por seleção pelos comportamentos esperados, com a contratação decidida pelo líder; cada pessoa ser contratada, movimentada ou desligada com o registro, a folha e os acessos atualizados; e cada pessoa nova ir à integração. O líder decide quem entra na sua equipe; a Gestão conduz e confere; o executivo decide o que passa da alçada na empresa, e o Administrador do IMTS.OS, nos círculos; os sócios decidem o desligamento de executivo ou de líder de círculo.", "frequencia": "Por evento: pedido do líder, plano de capacidade, mandato, saída, recurso liberado", "automacao_nivel": "média", "automacao_motivo": "Registrar, conferir orçamento e perfil, divulgar, triar e atualizar registros e acessos são de agente e automação; aprovar a abertura, conferir a decisão e fazer a proposta são de pessoa da Gestão; a escolha é do líder; o desligamento, com o executivo, o Administrador do IMTS.OS ou os sócios; o acerto rescisório é pago pela folha (GE-13), com o segundo aprovador dela.", "raias": ["Líder da equipe", "Pessoa", "Sócios", "Administrador do IMTS.OS", "Executivo da empresa", "Gestão · pessoa", "Gestão · agente", "Gestão · automação"]}, {"codigo": "GE-08", "circulo": 8, "nome": "Integrar pessoas novas à cultura", "dominio": "Pessoas e cultura", "classe": "essencial", "onda": 1, "objetivo": "Fazer cada pessoa nova, ou que mudou de papel, e cada pessoa de empresa adquirida entender o propósito, os valores e os comportamentos esperados, e sentir-se parte, antes de responder sozinha pelo seu papel: trilha montada pelo papel, conduzida com o líder, vínculos iniciais e verificação de entendimento e de pertencimento, com reforço combinado quando falta. A Identidade define o kit; a Gestão integra; o líder acompanha.", "frequencia": "Por pessoa: contratação, mudança de papel ou incorporação de empresa adquirida", "automacao_nivel": "média", "automacao_motivo": "Abrir, montar a trilha, conduzir as dúvidas, verificar e registrar são de agente e automação; combinar o reforço é de pessoa da Gestão; conversar e confirmar os comportamentos é do líder.", "raias": ["Líder da equipe", "Pessoa", "Gestão · pessoa", "Gestão · agente", "Gestão · automação"]}, {"codigo": "GE-09", "circulo": 8, "nome": "Avaliar e desenvolver as pessoas e medir a cultura", "dominio": "Pessoas e cultura", "classe": "essencial", "onda": 1, "objetivo": "Fazer cada pessoa ser avaliada pelos alvos e pelos comportamentos do kit de cultura, com as avaliações calibradas, as mudanças de remuneração propostas na política pela Gestão e aprovadas pelo executivo ou, nos círculos do IMTS.OS, pelo Administrador, e um plano de desenvolvimento combinado com o líder; quem quiser, ligar o seu propósito ao seu papel, com participação voluntária, a declaração guardada pela pessoa e o ajuste de papel só com o acordo dela; e a cultura e o engajamento serem medidos sem identificar quem respondeu e entregues à Identidade e à Inteligência. O líder avalia; a Gestão calibra, desenvolve e mede.", "frequencia": "A cada ciclo de avaliação e desenvolvimento e a cada pesquisa de cultura (cadências: avaliação semestral; pesquisa de cultura anual)", "automacao_nivel": "média", "automacao_motivo": "Preparar a avaliação, guiar a reflexão, acompanhar o treino e aplicar e analisar a pesquisa são de agente e automação; calibrar, propor a remuneração, aprovar treinos e apresentar o resultado são de pessoa da Gestão; avaliar é do líder; aprovar a remuneração é do executivo ou do Administrador do IMTS.OS.", "raias": ["Líder da equipe", "Pessoa", "Executivo da empresa", "Administrador do IMTS.OS", "Gestão · pessoa", "Gestão · agente", "Gestão · automação"]}, {"codigo": "GE-13", "circulo": 8, "nome": "Calcular e pagar a folha e os encargos", "dominio": "Pessoas e cultura", "classe": "essencial", "onda": 1, "objetivo": "Fazer cada folha ter o ponto, as variáveis, as comissões de quem vende sobre a receita recebida, os reconhecimentos e as mudanças de remuneração do período apurados a partir dos registros de pessoas, conferida pela Gestão, aprovada pelo executivo ou, nos círculos do IMTS.OS, pelo Administrador, paga no prazo e com os encargos recolhidos. A Gestão apura, confere e paga; quem aprova é outra pessoa.", "frequencia": "A cada período de folha (cadência: mensal; salário até o quinto dia útil do mês seguinte; FGTS até o dia 20)", "automacao_nivel": "média", "automacao_motivo": "Apurar, pagar e recolher são de agente e automação; conferir a folha é de pessoa da Gestão; aprovar é do executivo ou do Administrador do IMTS.OS.", "raias": ["Executivo da empresa", "Administrador do IMTS.OS", "Gestão · pessoa", "Gestão · agente", "Gestão · automação"]}, {"codigo": "GE-10", "circulo": 8, "nome": "Realizar os rituais de cultura e o reconhecimento de pessoas e equipes", "dominio": "Pessoas e cultura", "classe": "essencial", "onda": 1, "objetivo": "Reforçar, com cadência fixa, os comportamentos que os valores pedem: cada ritual preparado pelo padrão do kit de cultura, cada indicação de reconhecimento conferida com os critérios e decidida com os líderes, o ritual conduzido pelo líder, as histórias registradas e comunicadas e os reconhecimentos levados à folha. A Identidade define o padrão; a Gestão prepara, decide com os líderes e registra; o líder conduz.", "frequencia": "No calendário de rituais (cadência: trimestral)", "automacao_nivel": "média", "automacao_motivo": "Colher indicações, montar o roteiro, conferir com os critérios, selecionar histórias e registrar são de agente e automação; decidir os reconhecimentos é de pessoa da Gestão, com os líderes; conduzir o ritual é do líder.", "raias": ["Líder da equipe", "Gestão · pessoa", "Gestão · agente", "Gestão · automação"]}, {"codigo": "GE-11", "circulo": 8, "nome": "Planejar e publicar a comunicação interna", "dominio": "Pessoas e cultura", "classe": "essencial", "onda": 1, "objetivo": "Manter as pessoas informadas e alinhadas, com uma só voz: cada mudança na identidade, nos padrões e na estratégia, cada alvo, correção, mudança no portfólio e conteúdo externo relevante entrar na pauta; cada conteúdo ser redigido na voz e na marca vigentes, conferido, validado pela Governança quando sensível e aprovado; os materiais vencidos saírem dos canais; e o alcance e o entendimento serem medidos. A Identidade define a voz e as mensagens; a Gestão comunica para dentro; Relações, para fora.", "frequencia": "No calendário da comunicação interna (cadência: mensal) e por evento: fato ou mudança a comunicar", "automacao_nivel": "alta", "automacao_motivo": "Propor a pauta, redigir, conferir, publicar, retirar materiais vencidos e medir são de agente e automação; decidir a pauta e aprovar o conteúdo são de pessoa da Gestão.", "raias": ["Governança", "Gestão · pessoa", "Gestão · agente", "Gestão · automação"]}, {"codigo": "GE-12", "circulo": 8, "nome": "Gerir os ativos, os espaços e os serviços administrativos", "dominio": "Ativos e administração", "classe": "essencial", "onda": 1, "objetivo": "Fazer cada pedido de ativo, de espaço ou de serviço administrativo ser atendido pela melhor opção (comprar, alugar, remanejar ativo ocioso ou recusar), decidida pela Gestão dentro do orçamento; cada ativo ser registrado com o responsável e a depreciação, mantido e inventariado; e cada ativo ocioso, perdido ou no fim da vida ser baixado (vendido, doado, reciclado ou descartado), com os dados guardados nele eliminados. A Gestão decide e controla; a compra segue a jornada de compras.", "frequencia": "Por evento: pedido de ativo, espaço ou serviço; e a cada ciclo de manutenção e inventário (cadência: inventário anual; manutenção pelo plano de cada ativo)", "automacao_nivel": "alta", "automacao_motivo": "Avaliar o pedido, pedir a compra, registrar, programar a manutenção, inventariar e executar a baixa são de agente e automação; decidir o atendimento e o destino do ativo são de pessoa da Gestão.", "raias": ["Solicitante", "Gestão · pessoa", "Gestão · agente", "Gestão · automação"]}, {"codigo": "GO-01", "circulo": 9, "nome": "Manter as regras, as políticas e as alçadas de pessoas e agentes", "dominio": "Regras e decisões", "classe": "essencial", "onda": 1, "objetivo": "Fazer cada regra, política, alçada de pessoa ou de agente, regra de sigilo e de dados pessoais, regra de guarda, critério de rateio e modelo de proposta e de contrato nascer de um pedido, de uma decisão dos sócios ou de uma causa achada pela conformidade; ser redigida ouvidos os donos e, no rateio, a Estratégia; ser decidida pela Governança, dentro da sua alçada, ou pelos sócios; e ser publicada, versionada, a quem a usa. A Governança redige e publica; os sócios decidem as regras gerais e as alçadas dos executivos.", "frequencia": "Por evento: pedido, decisão dos sócios, mudança no catálogo de dados, contestação ou causa achada pela conformidade; e a cada revisão periódica (cadência: anual, e por evento)", "automacao_nivel": "média", "automacao_motivo": "Registrar, levantar o que vale, redigir, versionar e publicar são de agente e automação; revisar o risco jurídico e decidir dentro da alçada são de pessoa da Governança; as regras gerais, dos sócios.", "raias": ["Solicitante", "Sócios", "Estratégia", "Governança · pessoa", "Governança · agente", "Governança · automação"]}, {"codigo": "GO-02", "circulo": 9, "nome": "Secretariar as decisões dos sócios e cumprir os atos societários", "dominio": "Regras e decisões", "classe": "essencial", "onda": 1, "objetivo": "Fazer cada matéria que vai aos sócios chegar completa e dentro das regras, numa pauta convocada; cada decisão ser registrada em ata, com votos, responsável e prazo; cada ato societário (constituição, alteração ou encerramento de empresa) ser registrado nos órgãos; e cada decisão ter o cumprimento acompanhado e cobrado. Os círculos levam as matérias; os sócios decidem; a Governança secretaria, registra e acompanha.", "frequencia": "No calendário dos sócios (cadência: trimestral, e por evento) e por evento: matéria levada à decisão", "automacao_nivel": "média", "automacao_motivo": "Registrar a matéria, conferir se está completa, lavrar a ata e acompanhar o cumprimento são de agente e automação; fechar a pauta, conferir a ata e fazer os registros são de pessoa da Governança; decidir é dos sócios.", "raias": ["Solicitante", "Sócios", "Governança · pessoa", "Governança · agente", "Governança · automação"]}, {"codigo": "GO-03", "circulo": 9, "nome": "Gerir os riscos, a conformidade e os controles internos", "dominio": "Riscos e conformidade", "classe": "essencial", "onda": 1, "objetivo": "Fazer os riscos de cada círculo, empresa, oferta, contrato e agente serem reunidos, avaliados pela matriz e tratados por decisão; os controles internos e a conformidade serem testados; cada falha de controle ou não conformidade virar plano de remediação com dono e prazo e, quando a causa pede, regra nova ou revista; e o relatório de riscos e conformidade ir aos sócios e à Estratégia. A Governança avalia, testa e relata; os donos tratam os riscos e remediam.", "frequencia": "A cada ciclo de riscos e conformidade (cadência: trimestral) e por evento: risco, falha de controle ou mudança relevante", "automacao_nivel": "média", "automacao_motivo": "Reunir, avaliar pela matriz, testar controles e consolidar o relatório são de agente e automação; decidir o tratamento e montar a remediação são de pessoa da Governança, com os donos; o tratamento dos riscos de nota 15 ou mais é dos sócios.", "raias": ["Sócios", "Governança · pessoa", "Governança · agente", "Governança · automação"]}, {"codigo": "GO-04", "circulo": 9, "nome": "Manter em dia as obrigações legais: registros, certidões, marcas, procurações e seguros", "dominio": "Riscos e conformidade", "classe": "essencial", "onda": 1, "objetivo": "Fazer cada licença, certidão, registro de empresa e de marca, procuração e seguro estar no calendário com o prazo; cada obrigação ser cumprida antes de vencer, com as exigências do órgão atendidas e o indeferimento levado ao executivo; e as certidões e os documentos de habilitação estarem em dia para Negócios. A Governança mantém e cumpre; a Identidade decide a marca.", "frequencia": "Por prazo de cada obrigação e por evento: registro de marca, marca retirada, mandato, compra ou venda de empresa", "automacao_nivel": "média", "automacao_motivo": "Manter o calendário, apontar o que vence, preparar o pedido e registrar são de agente e automação; conferir, protocolar e cumprir as exigências são de pessoa da Governança.", "raias": ["Solicitante", "Executivo da empresa", "Governança · pessoa", "Governança · agente", "Governança · automação"]}, {"codigo": "GO-05", "circulo": 9, "nome": "Revisar os contratos, guardá-los e acompanhar prazos e obrigações", "dominio": "Contratos e auditoria", "classe": "essencial", "onda": 1, "objetivo": "Fazer cada contrato de cliente, de fornecedor, de tecnologia, de parceria, de oferta conjunta e de compra ou venda de empresa ser comparado com o modelo, ter a cláusula fora dele e o risco revisados e os poderes de quem assina conferidos; ser guardado com partes, prazos, valores e obrigações registrados; e ter cada vencimento e obrigação avisados ao dono com antecedência, com o vencimento sem decisão levado ao executivo. A frente dona origina e negocia o contrato; a Governança revisa, guarda e acompanha.", "frequencia": "Por evento: contrato a revisar ou a guardar; e por prazo de cada vencimento e obrigação", "automacao_nivel": "média", "automacao_motivo": "Comparar com o modelo, conferir poderes, guardar, registrar e avisar prazos são de agente e automação; revisar cláusulas e riscos, liberar o contrato e conferir o cumprimento são de pessoa da Governança.", "raias": ["Solicitante", "Sócios", "Executivo da empresa", "Governança · pessoa", "Governança · agente", "Governança · automação"]}, {"codigo": "GO-06", "circulo": 9, "nome": "Auditar se as entregas de pessoas e agentes seguem a identidade e a alçada", "dominio": "Contratos e auditoria", "classe": "essencial", "onda": 1, "objetivo": "Fazer uma amostra única de entregas de pessoas e agentes ser sorteada por círculo e por risco e servir à auditoria e à avaliação dos métodos pela Inteligência; cada entrega ser comparada com os critérios e os casos de teste da Identidade e com a alçada; cada caso de fronteira ser julgado pela Identidade e cada não conformidade pela Governança, com a causa achada; cada causa ir a quem corrige (o dono da entrega, a Identidade no padrão ambíguo, a Integração no desvio de agente); e o resultado ser publicado; e a própria Governança ser auditada uma vez por ano por assessoria externa, com as correções decididas pelos sócios. A Identidade define os critérios e julga os casos de fronteira; a Governança sorteia, julga as não conformidades e publica.", "frequencia": "A cada ciclo de auditoria (cadência: trimestral, antes da revisão da execução (ES-06)) e por evento: agente suspenso ou lacuna de execução apontada", "automacao_nivel": "alta", "automacao_motivo": "Sortear, comparar, classificar, achar a causa provável, calcular o índice e publicar são de agente e automação; julgar os casos, rever a amostra dos conformes e decidir a causa são de pessoa da Governança; uma vez por ano, a assessoria externa audita a própria Governança e os sócios decidem as correções.", "raias": ["Identidade", "Assessoria externa", "Sócios", "Governança · pessoa", "Governança · agente", "Governança · automação"]}, {"codigo": "GO-07", "circulo": 9, "nome": "Responder aos titulares de dados pessoais", "dominio": "Dados, crises e relatos", "classe": "essencial", "onda": 1, "objetivo": "Fazer cada pedido de titular de dados ser registrado, com a identidade do titular confirmada antes de qualquer resposta; os dados dele serem localizados no catálogo de dados, com quem os guarda; a resposta ser decidida pela Governança, no papel de encarregada, pelos direitos e pelas bases legais da LGPD, com os motivos informados quando o pedido não procede no todo ou em parte; a execução ser pedida a quem guarda os dados (Relações, na base de relacionamento, e os demais círculos); e o titular receber a resposta depois de conferido o cumprimento. A Governança decide; quem guarda o dado executa.", "frequencia": "Por evento: pedido de titular", "automacao_nivel": "alta", "automacao_motivo": "Registrar, confirmar a identidade, localizar os dados, propor a resposta, conferir o cumprimento e responder são de agente e automação; decidir a resposta é de pessoa da Governança.", "raias": ["Solicitante", "Governança · pessoa", "Governança · agente", "Governança · automação"]}, {"codigo": "GO-08", "circulo": 9, "nome": "Conduzir o comitê de crise, da declaração ao encerramento", "dominio": "Dados, crises e relatos", "classe": "essencial", "onda": 1, "objetivo": "Fazer cada alerta de crise de Relações acionar o comitê pelo protocolo, com assento da Identidade; os fatos, o risco jurídico e o dever de comunicar à autoridade serem conferidos, e esse dever levado ao canal próprio; a crise ser declarada ou não, com a posição, o porta-voz e o que pode ser dito propostos pela Governança e decididos por um único dono (o executivo, na crise da empresa; o Administrador do IMTS.OS, na crise do Ecossistema; os sócios, quando a crise envolve o executivo), e a decisão avisada a Relações; a posição ser revista enquanto a crise durar e o encerramento decidido pelo mesmo dono; e as lições irem à Identidade e à conformidade. Relações monitora e comunica; a Governança conduz o comitê e propõe; o dono da crise decide.", "frequencia": "Por evento: alerta de crise", "automacao_nivel": "média", "automacao_motivo": "Convocar, conferir fatos e obrigações, avisar e consolidar as lições são de agente e automação; propor a posição é de pessoa da Governança; decidir a posição e o encerramento é do dono da crise.", "raias": ["Relações", "Identidade", "Executivo da empresa", "Administrador do IMTS.OS", "Sócios", "Governança · pessoa", "Governança · agente", "Governança · automação"]}, {"codigo": "GO-09", "circulo": 9, "nome": "Receber relatos, apurar com independência e comunicar às autoridades", "dominio": "Dados, crises e relatos", "classe": "essencial", "onda": 1, "objetivo": "Fazer cada relato de conduta, fraude ou descumprimento ser registrado com a identidade de quem relata protegida, classificado e apurado com independência (o relato que cita alguém da Governança vai direto à assessoria externa, sem acesso da Governança, e a medida é dos sócios não envolvidos), com a medida decidida com o executivo ou, se ele, a Governança ou um sócio estiver envolvido, pelos sócios não envolvidos; cada incidente ou risco que a lei manda comunicar ser comunicado à autoridade competente pela Governança, salvo o do recall, que a Governança já comunica dentro da OP-07 e aqui só registra; e cada causa ir à conformidade. A Governança recebe, apura e comunica; os donos corrigem.", "frequencia": "Por evento: relato no canal; incidente ou risco a comunicar à autoridade", "automacao_nivel": "média", "automacao_motivo": "Registrar, propor a classificação, preparar a comunicação e registrar são de agente e automação; confirmar a classificação, apurar e enviar a comunicação são de pessoa da Governança.", "raias": ["Solicitante", "Executivo da empresa", "Sócios", "Assessoria externa", "Governança · pessoa", "Governança · agente", "Governança · automação"]}]$j$::jsonb) as x(codigo text, circulo smallint, nome text, dominio text, classe text, onda smallint, objetivo text, frequencia text, automacao_nivel text, automacao_motivo text, raias text[]);
